import{_ as e,o as t,c as s,a3 as n}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"架构与请求链路","description":"","frontmatter":{},"headers":[],"relativePath":"guide/go/architecture.md","filePath":"guide/go/architecture.md","lastUpdated":1789552132000}'),d={name:"guide/go/architecture.md"};function o(i,a,r,l,c,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="架构与请求链路" tabindex="-1">架构与请求链路 <a class="header-anchor" href="#架构与请求链路" aria-label="Permalink to &quot;架构与请求链路&quot;">​</a></h1><h2 id="应用启动" tabindex="-1">应用启动 <a class="header-anchor" href="#应用启动" aria-label="Permalink to &quot;应用启动&quot;">​</a></h2><p><code>cmd/server/main.go</code> 解析 flag 后调用 <code>bootstrap.Run</code>，按以下顺序启动：</p><ol><li>加载配置：Viper 读取 <code>configs/config.yaml</code>，环境变量以 <code>GA_</code> 前缀覆盖。</li><li>初始化 Zap 结构化日志（JSON 格式）。</li><li>初始化 GORM 数据库：MySQL / SQLite 自动切换 + 连接池（<code>max_open_conns: 50</code>）。</li><li>执行种子数据：超管账号 + 核心菜单。</li><li>扫描注册插件：L1 <code>init()</code> 自注册 + L2 ZIP 声明式加载。</li><li>注册 HTTP 路由：公开 / 认证 / 权限三级分组。</li><li>启动 MCP 网关。</li><li>发送 <code>app_startup</code> 事件。</li></ol><h2 id="后端分层" tabindex="-1">后端分层 <a class="header-anchor" href="#后端分层" aria-label="Permalink to &quot;后端分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP Request</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Middleware（request_id / cors / recovery / jwt_auth / permission / rate_limit / operation_log）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Gin Router（公开 / 认证 / 权限三级分组）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Handler（api/*.go）→ 参数校验 + 响应格式</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Service（service/）→ 业务逻辑</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>DAL（dal/）→ 数据访问</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>GORM Model（model/，sys_ 前缀）</span></span></code></pre></div><p>Handler 层负责参数绑定和统一响应格式 <code>{ code, msg, data }</code>；业务规则放在 Service 中；DAL 封装 GORM 查询。业务异常由 recovery 中间件捕获并转换为同样的错误结构。</p><h2 id="中间件链路" tabindex="-1">中间件链路 <a class="header-anchor" href="#中间件链路" aria-label="Permalink to &quot;中间件链路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中间件</th><th>职责</th></tr></thead><tbody><tr><td><code>request_id</code></td><td>为每个请求生成唯一 ID，贯穿日志链路</td></tr><tr><td><code>cors</code></td><td>跨域处理， Origins 由配置控制</td></tr><tr><td><code>recovery</code></td><td>捕获 panic，返回 500 而非崩溃</td></tr><tr><td><code>logger</code></td><td>请求/响应日志</td></tr><tr><td><code>jwt_auth</code></td><td>解析 Bearer Token，校验 JWT 有效性</td></tr><tr><td><code>login_guard</code></td><td>登录防爆破：5 次失败锁定 30 分钟</td></tr><tr><td><code>permission</code></td><td>基于权限标识的 RBAC 鉴权</td></tr><tr><td><code>rate_limit</code></td><td>每 IP 每分钟 300 次，burst 50</td></tr><tr><td><code>operation_log</code></td><td>操作日志异步写入审计队列</td></tr></tbody></table><h2 id="优雅关闭" tabindex="-1">优雅关闭 <a class="header-anchor" href="#优雅关闭" aria-label="Permalink to &quot;优雅关闭&quot;">​</a></h2><p>收到关闭信号后分三阶段执行，每阶段超时 5 秒：</p><ol><li>停止接收新请求（5s）。</li><li>插件卸载 + 发送 <code>app_shutdown</code> 事件（5s）。</li><li>日志 drain + 断开数据库连接（5s）。</li></ol>`,12)])])}const _=e(d,[["render",o]]);export{u as __pageData,_ as default};
